# Batch 9 — Hanuman texts (public-domain, traditional; Bajrang Baan attributed to Goswami Tulsidas). Meanings original.
D, C, M = "doha", "chaupai", "mantra"
BAJRANG_BAAN = [
 (D,"निश्चय प्रेम प्रतीति ते, बिनय करैं सनमान।\nतेहि के कारज सकल शुभ, सिद्ध करैं हनुमान॥","जो दृढ़ निश्चय, प्रेम और विश्वास के साथ विनय और सम्मान से प्रार्थना करते हैं, हनुमान जी उनके सारे शुभ काम सिद्ध कर देते हैं।"),
 (C,"जय हनुमंत संत हितकारी।\nसुन लीजै प्रभु अरज हमारी॥","संतों का हित करने वाले हनुमान जी, आपकी जय हो। हे प्रभु, हमारी विनती सुन लीजिए।"),
 (C,"जन के काज बिलंब न कीजै।\nआतुर दौरि महा सुख दीजै॥","अपने भक्त के काम में देर न कीजिए; जल्दी दौड़कर आइए और बड़ा सुख दीजिए।"),
 (C,"जैसे कूदि सिंधु महिपारा।\nसुरसा बदन पैठि बिस्तारा॥","जैसे आप कूदकर समुद्र के पार गए और सुरसा के फैले हुए मुँह में घुसकर (बाहर निकल आए)।"),
 (C,"आगे जाय लंकिनी रोका।\nमारेहु लात गई सुरलोका॥","आगे लंकिनी ने रोका तो आपने उसे लात मारी और वह सुरलोक चली गई।"),
 (C,"जाय बिभीषन को सुख दीन्हा।\nसीता निरखि परमपद लीन्हा॥","आपने विभीषण को सुख दिया और माता सीता के दर्शन करके परम आनंद पाया।"),
 (C,"बाग उजारि सिंधु महँ बोरा।\nअति आतुर जमकातर तोरा॥","अशोक वाटिका उजाड़कर (राक्षसों को) समुद्र में डुबो दिया और बड़ी तेज़ी से यमराज जैसे भयानक योद्धाओं को तोड़ डाला।"),
 (C,"अक्षय कुमार मारि संहारा।\nलूम लपेटि लंक को जारा॥","रावण के पुत्र अक्षय कुमार का संहार किया और पूँछ लपेटकर लंका जला दी।"),
 (C,"लाह समान लंक जरि गई।\nजय जय धुनि सुरपुर नभ भई॥","लंका लाख की तरह जल गई और देवलोक तथा आकाश में जय-जयकार गूँज उठी।"),
 (C,"अब बिलंब केहि कारन स्वामी।\nकृपा करहु उर अंतरयामी॥","हे स्वामी, अब किस कारण देर कर रहे हैं? हे हृदय की बात जानने वाले, कृपा कीजिए।"),
 (C,"जय जय लखन प्रान के दाता।\nआतुर ह्वै दुख करहु निपाता॥","लक्ष्मण जी को प्राण देने वाले (संजीवनी लाने वाले) आपकी जय हो; जल्दी आकर दुख का नाश कीजिए।"),
 (C,"जै हनुमान जयति बल-सागर।\nसुर-समूह-समरथ भट-नागर॥","बल के सागर हनुमान जी की जय; आप देवताओं के समूह में समर्थ और श्रेष्ठ योद्धा हैं।"),
 (C,"ॐ हनु हनु हनु हनुमंत हठीले।\nबैरिहि मारु बज्र की कीले॥","हे हठीले हनुमान, शत्रु को वज्र की कील से मारिए। (यहाँ ‘हनु’ का अर्थ है — नष्ट करो।)"),
 (C,"ॐ ह्नीं ह्नीं ह्नीं हनुमंत कपीसा।\nॐ हुं हुं हुं हनु अरि उर सीसा॥","हे कपियों के स्वामी हनुमान (बीज मंत्रों से आवाहन) — शत्रु के हृदय और सिर पर प्रहार कीजिए।"),
 (C,"जय अंजनि कुमार बलवंता।\nशंकरसुवन बीर हनुमंता॥","बलवान अंजनी-पुत्र की जय; आप शंकर के अवतार, वीर हनुमान हैं।"),
 (C,"बदन कराल काल-कुल-घालक।\nराम सहाय सदा प्रतिपालक॥","आपका रूप विकराल है, आप काल के कुल का भी नाश करने वाले हैं; आप श्रीराम के सहायक और सदा रक्षा करने वाले हैं।"),
 (C,"भूत, प्रेत, पिसाच निसाचर।\nअगिन बेताल काल मारी मर॥","भूत, प्रेत, पिशाच, निशाचर, अग्नि-बेताल और महामारी जैसे संकट —"),
 (C,"इन्हें मारु, तोहि सपथ राम की।\nराखु नाथ मरजाद नाम की॥","— इन सबको नष्ट कीजिए, आपको श्रीराम की शपथ है; हे नाथ, अपने नाम की मर्यादा रखिए।"),
 (C,"सत्य होहु हरि सपथ पाइ कै।\nराम दूत धरु मारु धाइ कै॥","श्रीहरि की शपथ पाकर (अपना वचन) सत्य कीजिए; हे रामदूत, दौड़कर (संकट को) पकड़िए और मारिए।"),
 (C,"जय जय जय हनुमंत अगाधा।\nदुख पावत जन केहि अपराधा॥","अथाह शक्ति वाले हनुमान जी की जय हो; आपका भक्त किस अपराध से दुख पा रहा है?"),
 (C,"पूजा जप तप नेम अचारा।\nनहिं जानत कछु दास तुम्हारा॥","आपका यह दास पूजा, जप, तप, नियम और आचार — कुछ भी नहीं जानता।"),
 (C,"बन उपबन मग गिरि गृह माहीं।\nतुम्हरे बल हौं डरपत नाहीं॥","वन में, बाग में, रास्ते में, पहाड़ पर या घर में — आपके बल के भरोसे मैं कहीं नहीं डरता।"),
 (C,"जनकसुता हरि दास कहावौ।\nताकी सपथ बिलंब न लावौ॥","आप जानकी और श्रीहरि के दास कहलाते हैं; उनकी शपथ है, देर न कीजिए।"),
 (C,"जै जै जै धुनि होत अकासा।\nसुमिरत होय दुसह दुख नासा॥","आकाश में जय-जय की ध्वनि हो रही है; आपका स्मरण करते ही असहनीय दुख नष्ट हो जाता है।"),
 (C,"चरन पकरि, कर जोरि मनावौं।\nयहि औसर अब केहि गोहरावौं॥","आपके चरण पकड़कर, हाथ जोड़कर मनाता हूँ; इस संकट की घड़ी में आपके सिवा और किसे पुकारूँ?"),
 (C,"उठु, उठु, चलु, तोहि राम दुहाई।\nपायँ परौं, कर जोरि मनाई॥","उठिए, उठिए, चलिए — आपको श्रीराम की दुहाई है; मैं पैरों पड़कर, हाथ जोड़कर मनाता हूँ।"),
 (C,"ॐ चं चं चं चं चपल चलंता।\nॐ हनु हनु हनु हनु हनुमंता॥","हे चंचल, तेज़ चलने वाले हनुमान (बीज मंत्रों से आवाहन) — संकट का नाश कीजिए।"),
 (C,"ॐ हं हं हाँक देत कपि चंचल।\nॐ सं सं सहमि पराने खल-दल॥","चंचल कपि जब हुंकार भरते हैं, तो दुष्टों का दल सहमकर भाग जाता है।"),
 (C,"अपने जन को तुरत उबारौ।\nसुमिरत होय आनंद हमारौ॥","अपने भक्त को तुरंत उबार लीजिए; आपका स्मरण करते ही हमें आनंद मिलता है।"),
 (C,"यह बजरंग-बाण जेहि मारै।\nताहि कहौ फिरि कवन उबारै॥","यह बजरंग बाण जिस (संकट) पर चलता है, बताइए फिर उसे कौन बचा सकता है?"),
 (C,"पाठ करै बजरंग-बाण की।\nहनुमत रक्षा करै प्रान की॥","जो बजरंग बाण का पाठ करता है, हनुमान जी उसके प्राणों की रक्षा करते हैं।"),
 (C,"यह बजरंग बाण जो जापैं।\nतासों भूत-प्रेत सब कापैं॥","जो इस बजरंग बाण का जाप करता है, उससे सारे भूत-प्रेत काँपते हैं।"),
 (C,"धूप देय जो जपै हमेसा।\nताके तन नहिं रहै कलेसा॥","जो धूप जलाकर सदा इसका जाप करता है, उसके शरीर में कोई कष्ट नहीं रहता।"),
 (D,"उर प्रतीति दृढ़, सरन ह्वै, पाठ करै धरि ध्यान।\nबाधा सब हर, करैं सब काम सफल हनुमान॥","जो हृदय में दृढ़ विश्वास रखकर, शरण में आकर, ध्यान लगाकर पाठ करता है — हनुमान जी उसकी सारी बाधाएँ हर लेते हैं और सब काम सफल करते हैं।"),
]
HANUMAN_MANTRA = [
 (M,"आञ्जनेय (हनुमान) गायत्री मंत्र\nॐ आञ्जनेयाय विद्महे वायुपुत्राय धीमहि।\nतन्नो हनुमत् प्रचोदयात्॥","हम अंजनी-पुत्र को जानें, वायु-पुत्र का ध्यान करें; वे हनुमान हमारी बुद्धि को प्रेरित करें।"),
 (M,"मनोजवं — हनुमान वंदना\nमनोजवं मारुततुल्यवेगं जितेन्द्रियं बुद्धिमतां वरिष्ठम्।\nवातात्मजं वानरयूथमुख्यं श्रीरामदूतं शरणं प्रपद्ये॥","मन जैसी गति और वायु जैसे वेग वाले, इंद्रियों को जीतने वाले, बुद्धिमानों में श्रेष्ठ, वायु-पुत्र, वानर सेना के प्रमुख, श्रीराम के दूत की मैं शरण लेता हूँ।"),
 (M,"हनुमान मूल मंत्र\nॐ हं हनुमते नमः॥","‘हं’ हनुमान जी का बीज अक्षर है — हनुमान जी को नमस्कार। मंगलवार और शनिवार को 108 बार जप किया जाता है।"),
 (M,"श्री हनुमते नमः\nॐ श्री हनुमते नमः॥","श्री हनुमान जी को नमस्कार — सबसे सरल नाम-मंत्र, जिसे कोई भी कभी भी जप सकता है।"),
 (M,"राम दूत मंत्र\nॐ नमो भगवते आञ्जनेयाय महाबलाय स्वाहा॥","भगवान आञ्जनेय, महाबली हनुमान को नमस्कार।"),
 (M,"बुद्धि-बल की प्रार्थना (हनुमान चालीसा से)\nबुद्धिहीन तनु जानिके, सुमिरौं पवन-कुमार।\nबल बुधि बिद्या देहु मोहिं, हरहु कलेस बिकार॥","स्वयं को बुद्धिहीन जानकर मैं पवनपुत्र का स्मरण करता हूँ — मुझे बल, बुद्धि और विद्या दीजिए और मेरे दुख-दोष दूर कीजिए।"),
]
